import type { GtcrnModule } from '../wasm-out/gtcrn.js'

const F32 = Float32Array.BYTES_PER_ELEMENT

export const FRAME_SIZE = 256
export const SAMPLE_RATE = 16000
export const FRAME_SIZE_48K = 768
export const SAMPLE_RATE_48K = 48000

export type SupportedSampleRate = typeof SAMPLE_RATE | typeof SAMPLE_RATE_48K

export interface GtcrnProcessorOptions {
  sampleRate?: SupportedSampleRate
}

export default class GtcrnProcessor {
  private readonly module: Readonly<GtcrnModule>
  private readonly processNative: (state: number, input: number, output: number) => void
  readonly frameSize: number
  readonly sampleRate: SupportedSampleRate

  private state: number
  private inPtr: number
  private outPtr: number

  constructor(module: Readonly<GtcrnModule>, options: GtcrnProcessorOptions = {}) {
    this.module = module
    this.sampleRate = options.sampleRate ?? SAMPLE_RATE
    if (this.sampleRate !== SAMPLE_RATE && this.sampleRate !== SAMPLE_RATE_48K) {
      throw new Error(`Unsupported sample rate: ${String(this.sampleRate)}.`)
    }
    this.frameSize = this.sampleRate === SAMPLE_RATE_48K ? FRAME_SIZE_48K : FRAME_SIZE
    this.processNative =
      this.sampleRate === SAMPLE_RATE_48K ? module._gtcrn_process_48k : module._gtcrn_process
    this.state = module._gtcrn_create()
    if (!this.state) {
      throw new Error('Failed to create GTCRN state.')
    }
    this.inPtr = module._malloc(this.frameSize * F32)
    this.outPtr = module._malloc(this.frameSize * F32)
    if (!this.inPtr || !this.outPtr) {
      this.destroy()
      throw new Error('Failed to allocate frame buffers.')
    }
  }

  /**
   * Denoise one frame. The default is 256 samples at 16 kHz; use
   * `{ sampleRate: 48000 }` for 768 samples at 48 kHz.
   */
  process(frame: Float32Array): Float32Array {
    if (!this.state) {
      throw new Error('GtcrnProcessor is destroyed.')
    }
    if (frame.length !== this.frameSize) {
      throw new Error(`frame must have exactly ${this.frameSize} samples at ${this.sampleRate} Hz.`)
    }
    // Re-read HEAPF32 every call: memory growth invalidates old views.
    this.module.HEAPF32.set(frame, this.inPtr / F32)
    this.processNative(this.state, this.inPtr, this.outPtr)
    return this.module.HEAPF32.slice(this.outPtr / F32, this.outPtr / F32 + this.frameSize)
  }

  destroy(): void {
    if (this.inPtr) this.module._free(this.inPtr)
    if (this.outPtr) this.module._free(this.outPtr)
    if (this.state) this.module._gtcrn_destroy(this.state)
    this.inPtr = this.outPtr = this.state = 0
  }
}
